package com.vandorlabs.screen;
import com.vandorlabs.persistence.PrimitiveData;
/** Exact earlier combined-frame artwork upgrade; catalogs and typed NBT remain platform-owned. */
public final class ScreenArtworkMigration {
 private ScreenArtworkMigration(){}
 public interface Tag extends PrimitiveData {boolean containsInt(String key);boolean containsString(String key);}
 public interface Catalog {boolean legacyFramed(String screen);String pairedBare(String framed);boolean validInput(String input);boolean framedChoice(int choice);int bareChoice(int choice);int defaultFrame();}
 public static String bare(String id){String result=id.replace("_framed_","_bare_").replace("/framed_","/bare_");return result.startsWith("framed_")?"bare_"+result.substring(7):result;}
 public static boolean framed(String id){return id!=null&&(id.contains("_framed_")||id.contains("/framed_")||id.startsWith("framed_"));}
 public static boolean needed(Tag tag,Catalog catalog){if(tag.containsInt("FrameFront"))return false;String selected=tag.getString("selectedScreen");int primary=tag.containsInt("PrimarySurfaceTexture")?tag.getInt("PrimarySurfaceTexture"):-1,secondary=tag.containsInt("SecondarySurfaceTexture")?tag.getInt("SecondarySurfaceTexture"):-1;return framed(selected)||!"engineering_screen".equals(selected)&&catalog.legacyFramed(selected)||framed(tag.getString("inputPanel"))||framed(tag.getString("secondaryInputPanel"))||catalog.framedChoice(primary)||catalog.framedChoice(secondary);}
 public static boolean migrate(Tag tag,Catalog catalog){if(!needed(tag,catalog))return false;String selected=tag.getString("selectedScreen"),input=tag.getString("inputPanel"),secondary=tag.getString("secondaryInputPanel");int primary=tag.containsInt("PrimarySurfaceTexture")?tag.getInt("PrimarySurfaceTexture"):-1,second=tag.containsInt("SecondarySurfaceTexture")?tag.getInt("SecondarySurfaceTexture"):-1;boolean explicit=framed(selected)||framed(input)||framed(secondary)||catalog.framedChoice(primary)||catalog.framedChoice(second);if(catalog.legacyFramed(selected)){String paired=catalog.pairedBare(selected);if(paired!=null){selected=paired;explicit=true;}}if(!explicit)return false;int frame=catalog.defaultFrame();if(frame<=0)throw new IllegalStateException("Missing legacy screen frame");tag.putInt("FrameFront",frame);tag.putBoolean("framed",false);if(tag.containsString("selectedScreen"))tag.putString("selectedScreen",bare(selected));if(tag.containsString("inputPanel"))tag.putString("inputPanel",bareInput(input,catalog));if(tag.containsString("secondaryInputPanel"))tag.putString("secondaryInputPanel",bareInput(secondary,catalog));if(tag.containsInt("PrimarySurfaceTexture"))tag.putInt("PrimarySurfaceTexture",catalog.bareChoice(primary));if(tag.containsInt("SecondarySurfaceTexture"))tag.putInt("SecondarySurfaceTexture",catalog.bareChoice(second));return true;}
 private static String bareInput(String input,Catalog catalog){String next=bare(input);return catalog.validInput(next)?next:input;}
}
